DELETE from accrual_t_pdc WHERE pdc_codice = ''; 

DO $$
 DECLARE 
	r RECORD; 
BEGIN 
	FOR r IN 
		SELECT 
			n.nspname AS schema_name, 
			c.relname AS table_name, 
			a.attname AS column_name, 
			pg_get_serial_sequence( 
				format('%I.%I', n.nspname, c.relname), 
				a.attname 
			) AS seq_name 
		FROM pg_class c 
		JOIN pg_namespace n ON n.oid = c.relnamespace 
		JOIN pg_attribute a ON a.attrelid = c.oid 
		WHERE c.relkind = 'r' 
		  AND a.attnum > 0 
		  AND pg_get_serial_sequence( 
				format('%I.%I', n.nspname, c.relname), 
				a.attname 
			  ) IS NOT NULL 
	LOOP 
		EXECUTE format( 
			'SELECT setval(%L, COALESCE((SELECT MAX(%I) FROM %I.%I), 1), true)', 
			r.seq_name, 
			r.column_name, 
			r.schema_name, 
			r.table_name 
		); 
	END LOOP; 
END $$; 






update accrual_t_pdc atp set pdc_classe_id = 2 where atp.pdc_codice in ('3','4','5') and pdc_livello = 1 and atp.ente_id =8 and atp.pdc_famiglia_id = 1 and atp.pdc_classe_id is null; 


update accrual_t_pdc atp set pdc_id_padre = (select pdc_id from accrual_t_pdc where pdc_codice = '3' and pdc_classe_id=7 and ente_id = 8) where atp.pdc_codice in ('3.2') and pdc_livello = 2 and pdc_siac = false and atp.ente_id =8 and atp.pdc_famiglia_id = 1; 

update accrual_t_pdc atp set pdc_id_padre = (select pdc_id from accrual_t_pdc where pdc_codice = '4' and pdc_classe_id=7 and ente_id = 8) where atp.pdc_codice in ('4.1') and pdc_livello = 2 and atp.ente_id =8 and atp.pdc_famiglia_id = 1; 

update accrual_t_pdc atp set pdc_id_padre = (select pdc_id from accrual_t_pdc where pdc_codice = '5' and pdc_classe_id=7 and ente_id = 8) where atp.pdc_codice in ('5.2') and pdc_livello = 2 and atp.ente_id =8 and atp.pdc_famiglia_id = 1; 

UPDATE accrual_t_pdc set pdc_fondo_dotazione = true WHERE pdc_codice_ufficiale = '3.1.1.0.0';

UPDATE accrual_t_pdc set pdc_foglia = true WHERE pdc_id in (SELECT pdc_id FROM accrual.accrual_t_pdc p WHERE p.pdc_id NOT IN ( SELECT DISTINCT pdc_id_padre FROM accrual.accrual_t_pdc WHERE pdc_id_padre IS NOT NULL)); 
update accrual.accrual_t_pdc set pdc_collegamento_bil_itas =NULL where pdc_collegamento_bil_itas =''; 
UPDATE accrual_t_pdc set pdc_foglia_non_foglia=true WHERE pdc_famiglia_id= (select pdc_famiglia_id from accrual_t_pdc_famiglia where pdc_famiglia_codice = 'ACCRUAL-A') and pdc_id NOT IN ( SELECT DISTINCT pdc_id_padre FROM accrual.accrual_t_pdc WHERE pdc_id_padre IS NOT null and pdc_famiglia_id=(select pdc_famiglia_id from accrual_t_pdc_famiglia where pdc_famiglia_codice = 'ACCRUAL-A')) and pdc_foglia=false; 

update accrual_t_pdc a set pdc_codice_ufficiale = (select b.pdc_codice from accrual_t_pdc b where a.pdc_id = b.pdc_id) where pdc_codice_ufficiale is null; 

DO $$
DECLARE 
    v_updated INTEGER := 1;
BEGIN
    WHILE v_updated > 0 LOOP
        
        UPDATE accrual_t_pdc atp
        SET pdc_collegamento_bil_itas = (
            SELECT atp2.pdc_collegamento_bil_itas
            FROM accrual_t_pdc atp2
            WHERE atp.pdc_id_padre = atp2.pdc_id
        )
        WHERE atp.pdc_famiglia_id IN (
                SELECT pdc_famiglia_id 
                FROM accrual_t_pdc_famiglia 
                WHERE pdc_famiglia_codice LIKE 'ACCRUAL%'
            )
          AND atp.pdc_collegamento_bil_itas IS NULL
          AND EXISTS (
                SELECT 1
                FROM accrual_t_pdc atp2
                WHERE atp.pdc_id_padre = atp2.pdc_id
                  AND atp2.pdc_collegamento_bil_itas IS NOT NULL
            );

        GET DIAGNOSTICS v_updated = ROW_COUNT;

        RAISE NOTICE 'Aggiornati: %', v_updated;

    END LOOP;
END $$;

