update accrual_t_azione set azione_urlapplicazione= replace(replace(azione_urlapplicazione, 'accrualwcl/', ''), '../', '') 
where azione_urlapplicazione is not null;

DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN
        SELECT
            n.nspname AS schema_name,
            c.relname AS table_name,
            a.attname AS column_name,
            pg_get_serial_sequence(
                format('%I.%I', n.nspname, c.relname),
                a.attname
            ) AS seq_name
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        JOIN pg_attribute a ON a.attrelid = c.oid
        WHERE c.relkind = 'r'
          AND a.attnum > 0
          AND pg_get_serial_sequence(
                format('%I.%I', n.nspname, c.relname),
                a.attname
              ) IS NOT NULL
    LOOP
        EXECUTE format(
            'SELECT setval(%L, COALESCE((SELECT MAX(%I) FROM %I.%I), 1), true)',
            r.seq_name,
            r.column_name,
            r.schema_name,
            r.table_name
        );
    END LOOP;
END $$;