INSERT INTO accrual.accrual_r_pdc_legame (pdc_legame_a_id, pdc_legame_b_id, pdc_tipo_relazione_id, ente_id, inizio_validita, fine_validita, gest_data_ins, gest_data_upd, gest_data_del, gest_utente_ins, gest_utente_upd, gest_utente_del) select p.pdc_id, arpl.pdc_legame_b_id, arpl.pdc_tipo_relazione_id, arpl.ente_id,arpl.inizio_validita, arpl.fine_validita, arpl.gest_data_ins, arpl.gest_data_upd, arpl.gest_data_del,arpl.gest_utente_ins, arpl.gest_utente_upd, arpl.gest_utente_del from accrual_t_pdc p, accrual_r_pdc_legame arpl, accrual_t_pdc_famiglia f where f.pdc_famiglia_id = p.pdc_famiglia_id and f.pdc_famiglia_codice like '%118%' and pdc_livello = 8 and pdc_legame_a_id = pdc_id_padre and p.ente_id = arpl.ente_id and p.ente_id=8;
INSERT INTO accrual_d_elaborazione_stato (elaborazione_stato_codice, elaborazione_stato_descrizione) SELECT stato, descrizione FROM ( VALUES 	('TRASMESSO', 'TRASMESSO DA SISTEMA ESTERNO'),    ('RIFIUTATO', 'RIFIUTATO PER ERRORI IN FASE DI ACQUISIZIONE'), 	('ELABORATO_IN_CORSO', 'ELABORAZIONE IN CORSO'), 	('I', 'IN CORSO'), 	('ELABORATO_IN_CORSO_ER', 'ELABORAZIONE IN CORSO CON ESITI ERRATO'), 	('ELABORATO_IN_CORSO_SC', 'ELABORAZIONE IN CORSO CON ESITI SCARTATO'), 	('ELABORATO_OK', 'ELABORATO CON ESITO POSITIVO'), 	('ELABORATO_KO', 'ELABORATO CON ESITO ERRATO - PRESENZA ERRORI / SCARTI'), 	('ELABORATO_ERRATO', 'ELABORATO CON ESITO ERRATO'), 	('ELABORATO_SCARTATO', 'ELABORATO CON ESITO SCARTATO'), 	('ANNULLATO', 'ANNULLATO'), 	('ACQUISITO', 'ACQUISITO')  ) AS t(stato, descrizione)  ON CONFLICT DO NOTHING;
INSERT INTO accrual_d_file_stato (file_stato_codice, file_stato_descrizione) SELECT stato, descrizione FROM ( VALUES 	('ELABORATO','Elaborato'), 	('DA_ELABORARE','Da elaborare'), 	('ANNULLATO','Annullato'), 	('IN_ELABORAZIONE','In elaborazione'), 	('CARICATO','Caricato'), 	('ELABORATO_CON_ERRORI','Elaborato con errori')  ) AS t(stato, descrizione)  ON CONFLICT DO NOTHING;
